 15→// File represents git file objects.
 16→type File struct {
 17→	// Name is the path of the file. It might be relative to a tree,
 18→	// depending of the function that generates it.
 19→	Name string
 20→	// Mode is the file mode.
 21→	Mode filemode.FileMode
 22→	// Blob with the contents of the file.
 23→	Blob
 24→}
 25→
 26→// NewFile returns a File based on the given blob object
 27→func NewFile(name string, m filemode.FileMode, b *Blob) *File {
 28→	return &File{Name: name, Mode: m, Blob: *b}
 29→}
 30→
 31→// Contents returns the contents of a file as a string.
 32→func (f *File) Contents() (content string, err error) {
 33→	reader, err := f.Reader()
 34→	if err != nil {
 35→		return "", err
 36→	}
 37→	defer ioutil.CheckClose(reader, &err)
 38→
 39→	buf := new(bytes.Buffer)
 40→	if _, err := buf.ReadFrom(reader); err != nil {
 41→		return "", err
 42→	}
 43→
 44→	return buf.String(), nil
 45→}
 46→
 47→// IsBinary returns if the file is binary or not
 48→func (f *File) IsBinary() (bin bool, err error) {
 49→	reader, err := f.Reader()
 50→	if err != nil {
 51→		return false, err
 52→	}
 53→	defer ioutil.CheckClose(reader, &err)
 54→
 55→	return binary.IsBinary(reader)
 56→}
 57→
 58→// Lines returns a slice of lines from the contents of a file, stripping
 59→// all end of line characters. If the last line is empty (does not end
 60→// in an end of line), it is also stripped.
 61→func (f *File) Lines() ([]string, error) {
 62→	content, err := f.Contents()
 63→	if err != nil {
 64→		return nil, err
 65→	}
 66→
 67→	splits := strings.Split(content, "\n")
 68→	// remove the last line if it is empty
 69→	if splits[len(splits)-1] == "" {
 70→		return splits[:len(splits)-1], nil
 71→	}
 72→
 73→	return splits, nil
 74→}
 75→
 76→// FileIter provides an iterator for the files in a tree.
 77→type FileIter struct {
 78→	s storer.EncodedObjectStorer
 79→	w TreeWalker
 80→}
 81→
 82→// NewFileIter takes a storer.EncodedObjectStorer and a Tree and returns a
 83→// *FileIter that iterates over all files contained in the tree, recursively.
 84→func NewFileIter(s storer.EncodedObjectStorer, t *Tree) *FileIter {
 85→	return &FileIter{s: s, w: *NewTreeWalker(t, true, nil)}
 86→}
 87→
 88→// Next moves the iterator to the next file and returns a pointer to it. If
 89→// there are no more files, it returns io.EOF.
 90→func (iter *FileIter) Next() (*File, error) {
 91→	for {
 92→		name, entry, err := iter.w.Next()
 93→		if err != nil {
 94→			return nil, err
 95→		}
 96→
 97→		if entry.Mode == filemode.Dir || entry.Mode == filemode.Submodule {
 98→			continue
 99→		}
100→
101→		blob, err := GetBlob(iter.s, entry.Hash)
102→		if err != nil {
103→			return nil, err
104→		}
105→
106→		return NewFile(name, entry.Mode, blob), nil
107→	}
108→}
109→
110→// ForEach call the cb function for each file contained in this iter until
111→// an error happens or the end of the iter is reached. If plumbing.ErrStop is sent
112→// the iteration is stop but no error is returned. The iterator is closed.
113→func (iter *FileIter) ForEach(cb func(*File) error) error {
114→	defer iter.Close()
115→
116→	for {
117→		f, err := iter.Next()
118→		if err != nil {
119→			if err == io.EOF {
120→				return nil
121→			}
122→
123→			return err
124→		}
125→
126→		if err := cb(f); err != nil {
127→			if errors.Is(err, storer.ErrStop) {
128→				return nil
129→			}
130→
131→			return err
132→		}
133→	}
134→}
135→
136→// Close releases resources associated with the iterator.
137→func (iter *FileIter) Close() {
138→	iter.w.Close()
139→}
