585→
586→	// Claude Code and other JSONL-based agents
587→	allLines := strings.Split(content, "\n")
588→	// Trim trailing empty lines (from final \n in JSONL)
589→	for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
590→		allLines = allLines[:len(allLines)-1]
591→	}
592→	return len(allLines)
593→}
